import {ImmediateColourSession,bindImmediateColour} from './immediate-colour.js';
import {find,walk,isLocked,clone} from '../document/model.js';
import {evaluated,setProperty} from '../animation/evaluate.js';
import {escape} from '../renderer/svg.js';

export function normalColour(value){if(typeof value!=='string')return null;value=value.trim().toLowerCase();if(/^#[0-9a-f]{3}$/.test(value))value='#'+[...value.slice(1)].map(c=>c+c).join('');return /^#[0-9a-f]{6}$/.test(value)?value:null;}
export function readRecentColours(storage){try{const values=JSON.parse(storage?.getItem('poppy-recent-colours')||'[]');return Array.isArray(values)?[...new Set(values.map(normalColour).filter(Boolean))].slice(0,10):[];}catch{return [];}}
export function addRecentColour(colour,storage,previous=[]){const normalized=normalColour(colour),history=[...new Set([...readRecentColours(storage),...previous.map(normalColour).filter(Boolean)])];if(!normalized)return history.slice(0,10);const colours=[normalized,...history.filter(c=>c!==normalized)].slice(0,10);try{storage?.setItem('poppy-recent-colours',JSON.stringify(colours));storage?.setItem('poppy-draw-color',normalized);}catch{}return colours;}
export function objectColourPatch(n,prop,colour,time){const v=evaluated(n,time),patch={[prop]:colour};if(prop==='fill'&&v.mesh)patch.mesh={...clone(v.mesh),points:v.mesh.points.map(p=>({...p,color:colour}))};if(prop==='stroke'&&v.strokeWidth<=0)patch.strokeWidth=2;return patch;}
export function colourTargets(a,n){const targets=[];walk([n],v=>{if(v.type!=='group'&&v.type!=='image'&&!isLocked(a.doc,v.id))targets.push(v);});return targets;}
export function showObjectColour(a,id=a.selected[0],property='auto'){
 const n=find(a.doc,id);if(!n||isLocked(a.doc,id))return a.toast('Select unlocked artwork to colour.');const targets=colourTargets(a,n);if(!targets.length)return a.toast('This layer has no editable fill or stroke.');a.activeColourDialog?.close();a.motionRecorder?.cancel({render:false});a.properties.flush();a.pause();a.stage.finishPath();
 const v=evaluated(targets[0],a.time);let prop=property==='auto'?(v.fill==='none'?'stroke':'fill'):property,colour=normalColour(v[prop])||a.drawColor||'#a8adb5';
 let recent;try{recent=readRecentColours(globalThis.localStorage);}catch{recent=[];}if(!recent.length)recent=(a.recentColours||[]).slice(0,10);
 const d=a.dialog('Colour · '+escape(n.name),`<form><div class="colour-targets" role="group" aria-label="Colour target"><button type="button" data-colour-target="fill">Fill</button><button type="button" data-colour-target="stroke">Stroke</button></div><div class="object-colour-preview" data-colour-sample></div><label>Colour<input type="color" data-colour-native aria-label="Choose colour" value="${colour}"></label><label>Hex colour<input name="hex" aria-label="Hex colour" value="${colour}" required></label><h3>Last 10 colours</h3><div class="recent-colours">${recent.length?recent.map(c=>`<button type="button" data-recent-colour="${c}" aria-label="Use ${c}" title="${c}" style="--swatch:${c}"><span></span></button>`).join(''):'<span class="subtle">Chosen colours will appear here.</span>'}</div><p class="subtle" data-colour-status></p><div class="dialog-actions"><button type="button" data-close>Done</button></div></form>`,undefined,{modal:false});d.classList.add('object-colour-dialog');a.activeColourDialog=d;
 const session=new ImmediateColourSession(a,{ids:targets.map(n=>n.id),ownerId:id,label:'Object colour',apply(value,time){for(const target of targets){const current=find(a.doc,target.id);if(!current||isLocked(a.doc,target.id))continue;for(const [key,colourValue] of Object.entries(objectColourPatch(current,prop,value,time)))setProperty(current,key,colourValue,time);}}});
 const update=(keepHex=false)=>{if(!keepHex)d.querySelector('[name=hex]').value=colour;d.querySelector('[data-colour-native]').value=colour;d.querySelector('[data-colour-sample]').style.background=colour;for(const b of d.querySelectorAll('[data-colour-target]')){b.classList.toggle('active',b.dataset.colourTarget===prop);b.setAttribute('aria-pressed',b.dataset.colourTarget===prop);}d.querySelector('[data-colour-status]').textContent=prop+' · Frame '+Math.round(a.time*a.doc.fps)+' · changes apply immediately · Undo restores the previous colour';};
 const choose=(value,discrete=false,keepHex=false)=>{value=normalColour(value);if(!value)return;if(!session.update(value,discrete)){session.close();d.close();return;}colour=value;update(keepHex);};
 d.querySelector('[data-colour-native]').oninput=e=>choose(e.target.value);d.querySelector('[name=hex]').oninput=e=>choose(e.target.value,false,true);for(const b of d.querySelectorAll('[data-recent-colour]'))b.onclick=()=>choose(b.dataset.recentColour,true);for(const b of d.querySelectorAll('[data-colour-target]'))b.onclick=()=>{session.flush();if(!session.valid())return d.close();prop=b.dataset.colourTarget;const current=find(a.doc,targets[0].id);colour=normalColour(evaluated(current,a.time)[prop])||a.drawColor;update();};bindImmediateColour(a,d,session);update();return d;
}
